@php
    $principal = (float) $loan->principal_amount;
    $principalPaid = (float) $loan->installments->sum('principal_paid');
    $interestDue = (float) $loan->installments->sum('interest_due');
    $interestPaid = (float) $loan->installments->sum('interest_paid');
    $feesDue = (float) $loan->installments->sum('fees_due');
    $feesPaid = (float) $loan->installments->sum('fees_paid');
    $penaltiesDue = (float) $loan->installments->sum('penalties_due');
    $totalContract = $principal + $interestDue + $feesDue + $penaltiesDue;
    $totalPaid = (float) $loan->repayments->where('status', 'Posted')->sum('amount');
    $outstanding = max(0, $totalContract - $principalPaid - $interestPaid - $feesPaid);
    $progress = $totalContract > 0 ? min(100, round($totalPaid / $totalContract * 100)) : 0;
    $paidInstallments = $loan->installments->where('status', 'Paid')->count();
    $overdueInstallments = $loan->installments->filter(fn ($item) => $item->status !== 'Paid' && $item->due_date->isPast())->count();
@endphp
